import hmac, hashlib

def verify_webhook(raw_payload, secret_key, expected_sig):
    computed = 'sha256=' + hmac.new(secret_key.encode(), raw_payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(computed, expected_sig)

